  "inlineSchema": "// ─── Prisma Schema for FitSpace ────────────────────────────\n// Models: User, Meal, Workout, WaterLog, SleepLog, MoodLog\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── User ──────────────────────────────────────────────────\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Goals\n  dailyWaterGoal    Float @default(2500) // ml\n  dailyCaloriesGoal Float @default(2000) // kcal\n  dailySleepGoal    Float @default(8) // hours\n  dailyWorkoutGoal  Int   @default(30) // minutes\n\n  // Profile (optional for AI context)\n  weight Float? // kg\n  height Float? // cm\n\n  meals Meal[]\n\n  workouts  Workout[]\n  waterLogs WaterLog[]\n  sleepLogs SleepLog[]\n  moodLogs  MoodLog[]\n}\n\n// ─── Meal ──────────────────────────────────────────────────\nmodel Meal {\n  id          String   @id @default(uuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id])\n  description String\n  mealType    String // breakfast, lunch, dinner, snack\n  calories    Float?\n  protein     Float?\n  carbs       Float?\n  fat         Float?\n  fiber       Float?\n  aiAnalysis  String? // raw AI response JSON\n  loggedAt    DateTime @default(now())\n  createdAt   DateTime @default(now())\n}\n\n// ─── Workout ───────────────────────────────────────────────\nmodel Workout {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  type      String // cardio, strength, flexibility, sports, etc.\n  name      String\n  duration  Int // minutes\n  calories  Float?\n  notes     String?\n  loggedAt  DateTime @default(now())\n  createdAt DateTime @default(now())\n}\n\n// ─── Water Intake ──────────────────────────────────────────\nmodel WaterLog {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  amount    Float // milliliters\n  loggedAt  DateTime @default(now())\n  createdAt DateTime @default(now())\n}\n\n// ─── Sleep ─────────────────────────────────────────────────\nmodel SleepLog {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  hours     Float\n  quality   Int // 1-5 rating\n  notes     String?\n  loggedAt  DateTime @default(now())\n  createdAt DateTime @default(now())\n}\n\n// ─── Mood / Wellness ───────────────────────────────────────\nmodel MoodLog {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  mood      String // happy, calm, stressed, tired, energetic, sad\n  energy    Int // 1-5\n  notes     String?\n  loggedAt  DateTime @default(now())\n  createdAt DateTime @default(now())\n}\n",
